import shutil
import subprocess
import json
import time
from pathlib import Path

def archive_stale_branch_to_folder(repo_path: str, branch: str, archive_dir: str):
    repo = Path(repo_path)
    if not (repo / '.git').exists():
        return {'error': 'not a git repository'}
    if branch in ('main', 'master'):
        return {'error': 'refusing to archive a protected branch'}
    bundle = repo / f"{branch.replace('/', '_')}.bundle"
    if not bundle.is_file():
        return {'error': 'bundle file not found'}
    dest = Path(archive_dir)
    if not dest.is_dir():
        return {'error': 'archive directory does not exist'}
    shutil.move(str(bundle), str(dest / bundle.name))
    # Record the archive event in a manifest file inside the archive directory
    manifest = dest / 'archive_manifest.json'
    entries = json.loads(manifest.read_text()) if manifest.is_file() else []
    entries.append({'branch': branch, 'bundle': bundle.name, 'archived_at': int(time.time())})
    manifest.write_text(json.dumps(entries, indent=2))
    subprocess.run(['git', '-C', str(repo), 'branch', '-D', branch], check=True)
    return {'archived': str(dest / bundle.name), 'deleted_branch': branch}
